      "fTerm": "NON-POSITIVE-DISPLACEMENT PUMPS (engine fuel-injection pumps <b>F02M</b>; ion pumps <b>H01J 41/12</b>; electrodynamic pumps <b>H02K 44/02</b>)<br><br><b><u>Note(s)</u></b><br><br><ul type=\"\"1\"\"><li>This subclass <u>covers</u> non-positive-displacement pumps for liquids, for elastic fluids, or for liquids and elastic fluids whether rotary or not having pure rotation.</li><li>This subclass <u>does not cover</u> combinations of non-positive-displacement pumps with other pumps, which are covered by subclass <b>F04B</b>, except that the use of such other pumps for priming or boosting non-positive-displacement is covered by this subclass.</li><li>Attention is drawn to the Notes preceding class <b>F01</b>, especially as regards the definition of &quot;pump&quot;.</li></ul><br><br><b><u>Subclass indexes</u></b><br><table width=\"100%\"><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">ROTARY PUMPS FOR LIQUID AND ELASTIC FLUID OR LIQUID ALONE</td><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Kind of flow: radial or helico-centrifugal; axial; circumferential or transverse; other</td><td><b>1/00</b>; <b>3/00</b>; <b>5/00</b>; <b>11/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">For handling specific fluids</td><td><b>7/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Priming, preventing vapour lock</td><td><b>9/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Pumping installations or systems; control</td><td><b>13/00</b>; <b>15/00</b></td></p></tr></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">ROTARY PUMPS FOR ELASTIC FLUID</td><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Kind of flow: radial or helico-centrifugal; axial; other</td><td><b>17/00</b>; <b>19/00</b>; <b>23/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Involving supersonic speed of fluid</td><td><b>21/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Pumping installations; control</td><td><b>25/00</b>; <b>27/00</b></td></p></tr></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">DETAILS OR ACCESSORIES</td><td><b>29/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">OTHER KINDS OF PUMPS</td><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Pumping liquid and elastic fluid at the same time</td><td><b>31/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">With other than pure rotation</td><td><b>33/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Wave producers</td><td><b>35/00</b></td></p></tr></p></tr></table>",
      "childFlag": 0,
      "sourceFile": "fi_F.txt",
      "kind": "fi"
